// src/pages/admin/OrgsPage.jsx
import { useEffect, useMemo, useState } from "react";
import { useAuth } from "../../context/AuthContext";
import { useToast } from "../../context/ToastContext";
import PageHeader from "../../components/shared/PageHeader";
import DataTable from "../../components/shared/DataTable";
import Badge from "../../components/shared/Badge";
import { donorApi, bankApi, ngoApi, fundApi } from "../../services/api";

const toSafeArray = (value) => (Array.isArray(value) ? value : []);

export default function OrgsPage() {
  const { user } = useAuth();
  const toast = useToast();
  const [loading, setLoading] = useState(false);
  const [snapshot, setSnapshot] = useState({ donors: [], banks: [], ngos: [], funds: [] });

  const userCert = user?.userCert || "admin";

  const loadSnapshot = async () => {
    setLoading(true);
    try {
      const [donorsRes, banksRes, ngosRes, fundsRes] = await Promise.allSettled([
        donorApi.getAll({ userCert }),
        bankApi.getAll({ userCert }),
        ngoApi.getAll({ userCert }),
        fundApi.getAll({ userCert }),
      ]);

      const donors = donorsRes.status === "fulfilled" ? toSafeArray(donorsRes.value?.data) : [];
      const banks = banksRes.status === "fulfilled" ? toSafeArray(banksRes.value?.data) : [];
      const ngos = ngosRes.status === "fulfilled" ? toSafeArray(ngosRes.value?.data) : [];
      const funds = fundsRes.status === "fulfilled" ? toSafeArray(fundsRes.value?.data) : [];

      setSnapshot({ donors, banks, ngos, funds });

      if ([donorsRes, banksRes, ngosRes, fundsRes].every((r) => r.status === "fulfilled")) {
        toast("Organization telemetry refreshed", "success");
      } else {
        toast("Some telemetry calls failed. Showing partial data.", "error");
      }
    } catch (error) {
      toast(error?.message || "Failed to load organization telemetry", "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadSnapshot();
  }, [userCert]);

  const orgRows = useMemo(() => {
    const activeFunds = snapshot.funds.filter((f) => String(f?.status || "").toUpperCase() === "ACTIVE").length;
    return [
      {
        id: "ORG001",
        name: "PlatformMSP",
        type: "Platform",
        status: "active",
        entities: 1,
        notes: "Network governance and onboarding control",
      },
      {
        id: "ORG002",
        name: "GovMSP",
        type: "Government",
        status: "active",
        entities: snapshot.donors.length + snapshot.banks.length,
        notes: `${snapshot.donors.length} donors • ${snapshot.banks.length} banks`,
      },
      {
        id: "ORG003",
        name: "NGOMSP",
        type: "NGO",
        status: "active",
        entities: snapshot.ngos.length,
        notes: `${snapshot.ngos.length} NGOs • ${activeFunds} active funds`,
      },
    ];
  }, [snapshot]);

  const fundRows = useMemo(() => {
    return snapshot.funds.slice(0, 10).map((fund) => ({
      fundId: fund?.fundId || fund?.id || "—",
      ngoId: fund?.ngoId || fund?.ngo || "—",
      status: String(fund?.status || "unknown"),
      raised: Number(fund?.totalTokens ?? fund?.currentAmount ?? fund?.raised ?? 0),
      target: Number(fund?.fundTarget ?? fund?.target ?? 0),
    }));
  }, [snapshot.funds]);

  return (
    <div>
      <PageHeader title="Organizations" desc="Live MSP telemetry and cross-org health overview" />

      <div className="card" style={{ marginBottom: 14 }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
          <div className="card-sub">Platform User Cert: <span className="mono">{userCert}</span></div>
          <button className="btn btn-secondary" onClick={loadSnapshot} disabled={loading}>
            {loading ? "Refreshing..." : "Refresh Telemetry"}
          </button>
        </div>
      </div>

      <div className="card" style={{ marginBottom: 14 }}>
        <DataTable
          columns={[
            { key: "id", label: "Org ID", mono: true },
            { key: "name", label: "MSP Name" },
            {
              key: "type",
              label: "Type",
              render: (r) => (
                <Badge type={r.type === "Platform" ? "gold" : r.type === "Government" ? "blue" : "purple"}>{r.type}</Badge>
              ),
            },
            { key: "status", label: "Status", render: (r) => <Badge type="green">{r.status}</Badge> },
            { key: "entities", label: "Entities" },
            { key: "notes", label: "Notes" },
          ]}
          data={orgRows}
        />
      </div>

      <div className="card">
        <div className="card-title" style={{ marginBottom: 8 }}>Recent Funds Snapshot</div>
        <DataTable
          columns={[
            { key: "fundId", label: "Fund ID", mono: true },
            { key: "ngoId", label: "NGO" },
            {
              key: "status",
              label: "Status",
              render: (r) => {
                const normalized = String(r.status || "").toUpperCase();
                const color = normalized === "ACTIVE" || normalized === "OPEN" ? "green" : "blue";
                return <Badge type={color}>{normalized}</Badge>;
              },
            },
            { key: "raised", label: "Raised" },
            { key: "target", label: "Target" },
          ]}
          data={fundRows}
          emptyText="No funds found"
        />
      </div>
    </div>
  );
}
